_REC = 8


def _index(prefix):
    """Binary search the packed table. `prefix` is 6 upper-case hex chars."""
    lo = 0
    hi = len(_T) // _REC - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        at = mid * _REC
        key = _T[at:at + 6]
        if key == prefix:
            return int(_T[at + 6:at + 8], 16)
        if key < prefix:
            lo = mid + 1
        else:
            hi = mid - 1
    return None


def lookup(mac):
    """(vendor, class) for a MAC, or (None, None) when nothing is known.

    Accepts 'aa:bb:cc:dd:ee:ff', 'AABBCCDDEEFF' or raw bytes. A
    locally-administered address (bit 1 of the first octet) is RANDOMISED and
    has no vendor at all -- phones and modern laptops do this by default --
    so it returns (None, 'random') rather than looking anything up. Reporting
    a manufacturer for a randomised MAC would be inventing one.
    """
    if isinstance(mac, (bytes, bytearray)):
        hexs = ''.join('{:02X}'.format(b) for b in mac)
    else:
        hexs = str(mac).replace(':', '').replace('-', '').upper()
    if len(hexs) < 6:
        return None, None
    try:
        first = int(hexs[0:2], 16)
    except Exception:
        return None, None
    if first & 0x02:
        return None, 'random'
    i = _index(hexs[0:6])
    if i is None:
        return None, None
    return VENDORS[i], CLASSES[i]


def prefix(mac):
    """The OUI as AA:BB:CC, for showing when no vendor is known."""
    if isinstance(mac, (bytes, bytearray)):
        hexs = ''.join('{:02X}'.format(b) for b in mac)
    else:
        hexs = str(mac).replace(':', '').replace('-', '').upper()
    return ':'.join((hexs[0:2], hexs[2:4], hexs[4:6])) if len(hexs) >= 6 else '?'
